import{D as e}from"./chunks/DemoVideo.Cxll-bB3.js";import{o as s,c as d,a2 as a,E as n}from"./chunks/framework.2Gs1zKBA.js";const c=JSON.parse('{"title":"力控与标定","description":"","frontmatter":{},"headers":[],"relativePath":"use-cases/force-calibration.md","filePath":"use-cases/force-calibration.md","lastUpdated":1793694501000}'),i={name:"use-cases/force-calibration.md"},h=Object.assign(i,{setup(l){return(r,t)=>(s(),d("div",null,[t[0]||(t[0]=a(`<h1 id="力控与标定" tabindex="-1">力控与标定 <a class="header-anchor" href="#力控与标定" aria-label="Permalink to &quot;力控与标定&quot;">​</a></h1><p>本案例演示力/位混合控制的三种基本场景，并汇总软件零位、动力学、运动学和手眼标定入口。力控和标定都依赖正确的安装方向、TCP、负载、重心与现场基准。</p><div class="danger custom-block"><p class="custom-block-title">真机操作提示</p><p>力控会持续向关节发送力矩，标定流程可能覆盖较大的关节范围。运行前必须固定接触面和标定工装，限制人员接近，检查完整轨迹，并确保紧急停止可用。示例结束时会失能机械臂；失能前必须可靠支撑机械臂及工具。</p></div><h2 id="演示目标" tabindex="-1">演示目标 <a class="header-anchor" href="#演示目标" aria-label="Permalink to &quot;演示目标&quot;">​</a></h2><p>力控示例依次完成以下流程：</p><ol><li>在基座 Z 方向施加 <code>-5 N</code>，持续 3 秒，其余方向保持位置；</li><li>释放 XYZ 三个平移方向，并在 Z 方向施加 <code>-3 N</code>，持续 3 秒；</li><li>注册绕 Y 轴旋转 30° 的倾斜坐标系，沿该坐标系法向施加 <code>-5 N</code>；</li><li>使用兼容旧 API 的 <code>task_frame</code> 重复倾斜面法向力控制；</li><li>退出力控并返回软件定义的关节零位。</li></ol><p>标定部分提供独立示例入口，不会在运行 <code>14_force_control.py</code> 时自动执行。</p><h2 id="安装与准备" tabindex="-1">安装与准备 <a class="header-anchor" href="#安装与准备" aria-label="Permalink to &quot;安装与准备&quot;">​</a></h2><p>进入 <code>onero-sdk</code> 仓库并安装动力学依赖：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/workspace/onero-sdk</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.[dynamics]&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>真机运行前还需要完成 <a href="/onerobot-A1/getting-started/hardware">CAN 接口配置与连接检查</a>，并确认：</p><ul><li>安装方向、TCP、工具与工件总质量和合成重心配置正确；</li><li>接触面柔软、固定，不会移动、破裂或夹伤人员；</li><li>已用较低目标力和有限持续时间确认坐标轴及力方向；</li><li>完整扫掠空间内无人，工具和线缆不会与环境干涉；</li><li>操作者理解 <code>force_mode_disable()</code> 只退出力控并恢复位置保持，不会失能。</li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th><code>selection</code></th><th><code>wrench</code></th><th style="text-align:right;">时间</th><th>说明</th></tr></thead><tbody><tr><td>Z 轴下压</td><td><code>[0,0,1,0,0,0]</code></td><td><code>[0,0,-5,0,0,0]</code></td><td style="text-align:right;">3 s</td><td>Z 轴力控，其余方向位置保持</td></tr><tr><td>XYZ 柔顺</td><td><code>[1,1,1,0,0,0]</code></td><td><code>[0,0,-3,0,0,0]</code></td><td style="text-align:right;">3 s</td><td>三个平移方向进入力控</td></tr><tr><td>倾斜面 <code>frame</code></td><td><code>[0,0,1,0,0,0]</code></td><td><code>[0,0,-5,0,0,0]</code></td><td style="text-align:right;">2 s</td><td>使用注册的 30° 倾斜坐标系</td></tr><tr><td>倾斜面 <code>task_frame</code></td><td><code>[0,0,1,0,0,0]</code></td><td><code>[0,0,-5,0,0,0]</code></td><td style="text-align:right;">2 s</td><td>旧 API 兼容写法</td></tr></tbody></table><p><code>selection</code> 中的 <code>1</code> 表示对应方向使用力控，<code>0</code> 表示保持位置；力的单位为 N，力矩的单位为 N·m。示例值不是所有工具和接触面的通用参数。</p><h2 id="操作阶段" tabindex="-1">操作阶段 <a class="header-anchor" href="#操作阶段" aria-label="Permalink to &quot;操作阶段&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">顺序</th><th>接口或阶段</th><th>操作含义</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td><code>movej()</code></td><td>进入预设接触准备姿态</td></tr><tr><td style="text-align:right;">2</td><td>场景 1</td><td>在 Z 方向持续施加 <code>-5 N</code></td></tr><tr><td style="text-align:right;">3</td><td>场景 2</td><td>XYZ 方向柔顺并在 Z 方向施加 <code>-3 N</code></td></tr><tr><td style="text-align:right;">4</td><td>场景 3A</td><td>使用 <code>frame=</code> 指定倾斜面参考坐标系</td></tr><tr><td style="text-align:right;">5</td><td>场景 3B</td><td>使用 <code>task_frame=</code> 验证旧 API 兼容性</td></tr><tr><td style="text-align:right;">6</td><td><code>movej()</code></td><td>返回软件定义的关节零位</td></tr><tr><td style="text-align:right;">7</td><td><code>disable()</code></td><td>撤销电机保持力矩</td></tr></tbody></table><p>每个力控场景结束后都会调用 <code>force_mode_disable()</code>，退出当前力控并恢复位置保持。</p><h2 id="真机运行" tabindex="-1">真机运行 <a class="header-anchor" href="#真机运行" aria-label="Permalink to &quot;真机运行&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/14_force_control.py</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>正常运行时，终端依次输出：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>场景 1: Z 轴下压 5N (持续 3 秒)</span></span>
<span class="line"><span>  完成</span></span>
<span class="line"><span></span></span>
<span class="line"><span>场景 2: XYZ 平面自由 + Z 轴下压 (持续 3 秒)</span></span>
<span class="line"><span>  完成</span></span>
<span class="line"><span></span></span>
<span class="line"><span>场景 3: 在倾斜面上施加法向力</span></span>
<span class="line"><span>  方式 A: 用 frame= 指定力控参考坐标系</span></span>
<span class="line"><span>  完成</span></span>
<span class="line"><span>  方式 B: 用 task_frame= (旧 API 兼容)</span></span>
<span class="line"><span>  完成</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div>`,22)),n(e,{src:"/videos/tools-advanced/08_force_control.mp4",title:"力控与柔顺控制"}),t[1]||(t[1]=a('<p><a href="https://github.com/lvwenyi01/onero-sdk/blob/master/examples/14_force_control.py" target="_blank" rel="noreferrer">查看力控源码</a></p><h2 id="标定入口" tabindex="-1">标定入口 <a class="header-anchor" href="#标定入口" aria-label="Permalink to &quot;标定入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>目的</th><th>示例入口</th></tr></thead><tbody><tr><td>软件零位</td><td>建立可复现的用户关节零位</td><td><a href="/onerobot-A1/advanced/#软件零位">软件零位说明</a></td></tr><tr><td>动力学标定</td><td>辨识惯性和关节摩擦参数</td><td><a href="https://github.com/lvwenyi01/onero-sdk/blob/master/examples/15_dynamics_calibration.py" target="_blank" rel="noreferrer">动力学标定示例</a></td></tr><tr><td>运动学标定</td><td>修正关节原点并改善模型一致性</td><td><a href="https://github.com/lvwenyi01/onero-sdk/blob/master/examples/16_kinematic_calibration.py" target="_blank" rel="noreferrer">运动学标定示例</a></td></tr><tr><td>手眼标定</td><td>求解相机与法兰或基座之间的变换</td><td><a href="https://github.com/lvwenyi01/onero-sdk/blob/master/examples/17_camera_calibration.py" target="_blank" rel="noreferrer">手眼标定示例</a></td></tr></tbody></table><p>标定文件不得在不同机械臂、序列号、安装方向或工具配置之间直接复用。</p><h2 id="结果判断" tabindex="-1">结果判断 <a class="header-anchor" href="#结果判断" aria-label="Permalink to &quot;结果判断&quot;">​</a></h2><p>力控运行成功应同时满足：</p><ul><li>三组场景按顺序完成，接触力方向与所选坐标系一致；</li><li>进入和退出接触过程平稳，没有振荡、冲击或持续位置漂移；</li><li>每个场景结束后退出力控，最后返回关节零位；</li><li>终端没有通信、限位或动力学异常。</li></ul><p>标定结果还应按类型判断：动力学标定的 <code>residual_rms</code> 是力矩模型拟合残差，不是末端定位精度；运动学标定的 <code>residual_mm</code> 只描述采集触点的模型收敛程度，必须使用独立检测点验证；手眼标定还需要相机内参、同步采集和未参与求解的数据验证。</p><p>所有标定结果都应与型号、序列号、左右侧、安装方向、工具、固件和 SDK 版本一起保存。</p><h2 id="中断与安全状态" tabindex="-1">中断与安全状态 <a class="header-anchor" href="#中断与安全状态" aria-label="Permalink to &quot;中断与安全状态&quot;">​</a></h2><p>若接触力方向错误、工具滑动、接触面松动或机械臂出现振荡，应立即使用现场适用的安全措施。不能通过增大目标力、延长持续时间或提高刚度来绕过异常。</p><p>程序正常结束或发生异常时会调用 <code>disable()</code>；这会撤销保持力矩，不是普通停止。异常发生在力控循环内时，不应仅依赖终端退出判断设备状态，必须现场确认机械臂已经停止并得到可靠支撑。</p><p>完整流程、参数边界和常见问题见<a href="/onerobot-A1/advanced/#标定">示教、力控与标定</a>。</p>',13))]))}});export{c as __pageData,h as default};
